async function confirmIssueDelete(issue,onDeleted){const dialog=document.createElement("dialog");dialog.className="issue-delete-dialog";dialog.innerHTML=`<form method="dialog"><h2>이 이슈를 삭제할까요?</h2><p>삭제하면 이 이슈와 관련 사진을 다시 복구할 수 없습니다.</p><p class="issue-delete-status" role="status"></p><div class="issue-delete-actions"><button type="button" class="secondary issue-delete-cancel">취소</button><button type="button" class="danger issue-delete-confirm">삭제</button></div></form>`;document.body.append(dialog);const cancel=dialog.querySelector(".issue-delete-cancel"),confirm=dialog.querySelector(".issue-delete-confirm"),status=dialog.querySelector(".issue-delete-status");cancel.onclick=()=>dialog.close();dialog.addEventListener("close",()=>dialog.remove(),{once:true});confirm.onclick=async()=>{confirm.disabled=cancel.disabled=true;status.textContent="삭제하는 중입니다.";try{await api(`/issues/${issue.id}`,{method:"DELETE"});dialog.close();await onDeleted?.(issue.id)}catch(error){status.textContent=`삭제하지 못했습니다. ${error.message}`;confirm.disabled=cancel.disabled=false}};dialog.showModal()}
const compactTitle=title=>{const value=String(title||"").replace(/^\s*(?:(?:\d+동|상가동|관리동|커뮤니티센터|경비실|기계실|전기실|지하\d+층\s*주차장|지상주차장|외부|공용부|기타)\s*)*(?:(?:지하\d+층|지상층|\d+층)\s*)?(?:\d+호\s*)?(?:(?:현관|거실|주방|침실[1-4]|부부욕실|공용욕실|욕실[12]|발코니|다용도실|드레스룸|복도|계단실|엘리베이터홀|공용부|외부|옥상|지하|기타)\s*)?/,"").trim();return value||String(title||"")};
