async function createSharePhoto(issue){const response=await fetch(`/api/v1/issues/${issue.id}/media/original`,{credentials:"include",cache:"no-store"});if(!response.ok)throw new Error("사진을 불러오지 못했습니다.");const bitmap=await createImageBitmap(await response.blob()),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement("canvas"),width=Math.max(1,Math.round(bitmap.width*scale)),height=Math.max(1,Math.round(bitmap.height*scale)),captionHeight=Math.max(120,Math.min(260,Math.round(height*.22))),ctx=canvas.getContext("2d");canvas.width=width;canvas.height=height;ctx.drawImage(bitmap,0,0,width,height);bitmap.close();ctx.fillStyle="rgba(0,0,0,.78)";ctx.fillRect(0,height-captionHeight,width,captionHeight);ctx.fillStyle="#fff";ctx.textBaseline="top";const headerSize=Math.max(24,Math.round(width*.032)),descriptionSize=Math.max(18,Math.round(width*.023)),dateSize=Math.max(1,Math.round(descriptionSize*.95)),date=formatIssuePhotoDateKst(issue.createdAt),gap=Math.max(18,Math.round(width*.018));ctx.font=`700 ${dateSize}px sans-serif`;const dateWidth=date?ctx.measureText(date).width:0,locationWidth=Math.max(0,width-56-dateWidth-(date?gap:0));ctx.font=`700 ${headerSize}px sans-serif`;const location=fitWatermarkLocation(issue.location||"위치 정보 없음",locationWidth,text=>ctx.measureText(text).width);ctx.textAlign="left";ctx.fillText(location,28,height-captionHeight+22,locationWidth);if(date){ctx.font=`700 ${dateSize}px sans-serif`;ctx.textAlign="right";ctx.fillText(date,width-28,height-captionHeight+22);ctx.textAlign="left"}ctx.font=`500 ${descriptionSize}px sans-serif`;const description=String(issue.description||issue.title||"내용 없음"),words=description.split(/\s+/);let line="",y=height-captionHeight+70;for(const word of words){const next=line?`${line} ${word}`:word;if(ctx.measureText(next).width>width-56&&line){ctx.fillText(line,28,y);line=word;y+=Math.max(26,Math.round(width*.03));if(y>height-34)break}else line=next}if(line&&y<=height-34)ctx.fillText(line,28,y);const blob=await new Promise((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(new Error("\uD3B8\uC9D1 \uC774\uBBF8\uC9C0 \uD569\uC131\uC5D0 \uC2E4\uD328\uD588\uC2B5\uB2C8\uB2E4.")),"image/jpeg",.9));return new File([blob],"GUI-Arc-share-photo.jpg",{type:"image/jpeg"})}
async function shareIssuePhoto(issue,output){try{if(output)output.textContent="공유사진 만드는 중";const file=await createSharePhoto(issue);if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]}))){await navigator.share({files:[file]})}else{const url=URL.createObjectURL(file),anchor=document.createElement("a");anchor.href=url;anchor.download="GUI-Arc-share-photo.jpg";anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}if(output)output.textContent="공유사진을 준비했습니다."}catch(error){if(output)output.textContent="공유사진을 만들지 못했습니다"}}
createSharePhoto=async function(issue){const response=await fetch(`/api/v1/issues/${issue.id}/media/original`,{credentials:"include",cache:"no-store"});if(!response.ok)throw new Error("사진을 불러오지 못했습니다.");const bitmap=await createImageBitmap(await response.blob()),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement("canvas"),width=Math.max(1,Math.round(bitmap.width*scale)),height=Math.max(1,Math.round(bitmap.height*scale)),ctx=canvas.getContext("2d"),layout=issueShareWatermarkLayout(width,height),display=issueShareDisplay(issue);canvas.width=width;canvas.height=height;ctx.drawImage(bitmap,0,0,width,height);bitmap.close();ctx.fillStyle=`rgba(0,0,0,${layout.overlayAlpha})`;ctx.fillRect(0,height-layout.footerHeight,width,layout.footerHeight);ctx.fillStyle="#fff";ctx.shadowColor="rgba(0,0,0,.55)";ctx.shadowBlur=2;ctx.textBaseline="top";const date=formatIssuePhotoDateKst(issue.createdAt),headingY=height-layout.footerHeight+layout.padding;ctx.font=`700 ${layout.dateSize}px sans-serif`;const dateWidth=date?ctx.measureText(date).width:0,locationWidth=Math.max(0,width-layout.padding*2-dateWidth-(date?layout.gap:0));ctx.font=`700 ${layout.locationSize}px sans-serif`;const location=fitWatermarkLocation(display.location,locationWidth,text=>ctx.measureText(text).width);ctx.textAlign="left";ctx.fillText(location,layout.padding,headingY,locationWidth);if(date){ctx.font=`700 ${layout.dateSize}px sans-serif`;ctx.textAlign="right";ctx.fillText(date,width-layout.padding,headingY);ctx.textAlign="left"}ctx.font=`500 ${layout.contentSize}px sans-serif`;const contentLines=wrapWatermarkContent(display.content,width-layout.padding*2,text=>ctx.measureText(text).width,2);contentLines.forEach((line,index)=>ctx.fillText(line,layout.padding,layout.contentTop+layout.contentLineHeight*index));const blob=await new Promise((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(new Error("편집 이미지 합성에 실패했습니다.")),"image/jpeg",.9));return new File([blob],"GUI-Arc-share-photo.jpg",{type:"image/jpeg"})};
const downloadIssueShareFile=file=>{const url=URL.createObjectURL(file),anchor=document.createElement("a");anchor.href=url;anchor.download="GUI-Arc-share-photo.jpg";anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
shareIssuePhoto=async function(issue,output){try{if(output)output.textContent="공유사진 만드는 중";const file=await createSharePhoto(issue),result=await deliverIssueShareFile(file,{share:navigator.share?.bind(navigator),canShare:navigator.canShare?.bind(navigator),download:downloadIssueShareFile});if(output)output.textContent=result==="CANCELLED"?"공유를 취소했습니다.":"공유사진을 준비했습니다."}catch{if(output)output.textContent="공유사진을 만들지 못했습니다"}};
