function decorateCreationMediaCounts(issues){const top=document.querySelector(".issue-slide-top");if(top&&!top.querySelector(".issue-create-from-photo")){const create=document.createElement("a");create.className="primary action-link issue-create-from-photo";create.href="/issues/new";create.textContent="+ 이슈등록";top.append(create)}document.querySelectorAll(".issue-card,.issue-row").forEach((element,index)=>{const count=Number(issues[index]?.creationMediaCount||0);if(count>1){const badge=document.createElement("span");badge.className="issue-media-count";badge.textContent=`+${count-1}`;element.append(badge)}})}
function fieldDraftChoice(event){const anchor=event.target.closest?.('a[href="/issues/new"]');if(!anchor||location.pathname==="/issues/new")return;const hasDraft=fieldMultiPhotoDraft.photos.length||Object.values(fieldMultiPhotoDraft.fields).some(Boolean);if(!hasDraft)return;if(confirm("작성 중인 이슈가 있습니다. 이어서 작성할까요?"))return;if(confirm("기존 작성 내용을 지우고 새로 작성할까요?")){for(const item of fieldMultiPhotoDraft.photos)URL.revokeObjectURL(item.url);fieldMultiPhotoDraft.photos=[];fieldMultiPhotoDraft.fields={};fieldMultiPhotoDraft.selectedIndex=0;return}event.preventDefault()}
export async function renderIssuePage(input){document.removeEventListener("click",fieldDraftChoice);document.addEventListener("click",fieldDraftChoice);state={...state,...input};performance?.mark?.("issue-route-start");try{const path=location.pathname;if(path==="/issues/new"||path==="/pwa/issues/new")await createV3();else if(path==="/issues/open")await list("UNHANDLED");else if(path==="/issues/review")await list("review");else if(path==="/issues/completed")await list("completed");else if(path==="/issues/statistics"){const data=await api("/issues/summary");state.content.innerHTML=header("통계","현재 현장의 이슈 상태별 건수입니다.")+`<div class="summary-grid">${Object.entries(data.counts).map(([status,count])=>`<article class="card"><span>${escapeHtml(LABEL[status]||status)}</span><strong>${count}</strong></article>`).join("")}</div>`}else{const match=path.match(/^\/issues\/([^/]+)$/);match?await detail(match[1]):await list()}}catch(error){fail(error)}finally{performance?.mark?.("issue-first-usable")}}
